assert 14000 <= CN <= 15500, CN  # 8b 仅完成 68 段安全凝缩；结构性下放在 8c 继续
cites = sorted(set(int(x) for t in re.findall(r'\[(\d+(?:,\s*\d+)*)\]', txt) for x in re.findall(r'\d+', t)))
assert cites == list(range(1, 49)), cites[:4]
figs = [int(re.match(r'^Fig\. (\d+)\.', p.text).group(1)) for p in m.paragraphs if re.match(r'^Fig\. \d+\.', p.text)]
assert figs == [1, 2, 3, 4, 5, 6], figs
stxt = '\n'.join(p.text for p in s.paragraphs)
for key in ['Fig. S4. Workbench', 'Fig. S5. Interactive', 'Fig. S6. Editable', 'Fig. S7. Global-consistency', '图 S5 的 GUI', '从图 S7 可以观察到']:
    assert key in stxt, key
assert 'Fig. S1. Workbench' not in stxt and 'Fig. S2. Interactive' not in stxt
m.save(MAIN); s.save(SUPP)
print('OK round8b | main CN=%d | figs=%s | supp figs S1-S7' % (CN, figs))
